import copy
import json
import os

import requests
from requests.exceptions import ConnectionError
from ute_common_util.checksum import generate_md5

from ..exception import (
    FileDoesNotExist,
    HTTPConnectionException,
    IncompleteData,
    TestInstanceNotExistent,
    WrongMessageId,
)
from ..utils.logger import logger


class RPEndpoint:

    def __init__(self, url, description, retry_message=""):
        self.url = url
        self.description = description
        self.retry_message = retry_message

    def __bool__(self):
        return True if self.url else False


class ReportingPortalClient:
    def __init__(self, rp_url=None, json_url=None, events_url=None):
        """Client used for communication with Reporting Portal"""
        self._rp_url = rp_url
        self._json_url = json_url
        self._events_url = events_url

    def send_zip_report(self, zipfile_path):
        """Send a zipped file containing a report and other needed files to Reporting Portal.

        :param string   zipfile_path:     Path to zipfile containing report.

        :return: Response of request to send zip report
        :rtype: Response
        """
        logger.info("Sending zipped report to Reporting Portal")
        logger.debug(f"Report path: {zipfile_path}")
        response = ReportingPortalZipReport(self._rp_url).send(zipfile_path)
        return response

    def get_crt(
        self,
        test_lab_path=None,
        test_set_name=None,
        test_instance_name=None,
        test_instance_id=None,
    ):
        """Getting CRT status information from Reporting Portal.

        :return: Status of CRT. Possible: rg_CIT, rg_CRT1, rg_CRT2, rg_manual.
                                          nf_CIT, nf_CRT1, nf_CRT2, nf_manual
        :rtype: String
        """
        rp_crt = ReportingPortalCrt(self._json_url)
        json_cmd = rp_crt.build(
            test_lab_path, test_set_name, test_instance_name, test_instance_id
        )
        response = rp_crt.send(json_cmd)
        if not response.check_http() and not response.check_json(rp_crt.message_id):
            return response.json["result"]

    def report_event(self, method, date_time, **kwargs):
        """Getting CRT status information from Reporting Portal.

        :param string               method:     Name of method to be executed. Possible: user_new, user_login,
                                                reservation_new, test_execution_new, test_execution_status
        """
        rp_event = ReportingPortalEvent(self._events_url)
        json_cmd = rp_event.build(method, date_time, **kwargs)
        response = rp_event.send(json_cmd)
        response.check_http()
        return json_cmd["id"]

    def validate_configs(self, configs, sw_version):
        """Validating QC configurations.

        :param ConfigsStore    configs:     List of configs to be validated
        :param String          sw_version:  Build version
        """
        rp_validation = ReportingPortalConfigValidation()
        validation_data = [
            sw_version,
            configs.to_dicts()
        ]
        response = rp_validation.send(validation_data)
        return response.json


class ReportingPortalZipReport:
    reporting_portal_microservice_url = RPEndpoint(
        url="https://rep-portal.wroclaw.nsn-rdnet.net/testbook/upload/robot/",
        description="Primary RP address",
        retry_message="Retrying with primary address by IP",
    )

    reporting_portal_microservice_url_by_ip = RPEndpoint(
        url="http://10.42.7.71/testbook/upload/robot/",
        description="Primary RP address by IP",
        retry_message="Retrying with secondary address by IP",
    )

    reporting_portal_production_url_by_ip = RPEndpoint(
        url="http://10.42.7.71/at/upload/robot/", description="Secondary address by IP"
    )

    reporting_portal_endpoints = [
        reporting_portal_microservice_url,
        reporting_portal_microservice_url_by_ip,
        reporting_portal_production_url_by_ip,
    ]

    def __init__(self, rp_url=None):
        """Class used for managing report sending

        :param string   rp_url: Link used for communication with RP
        """
        self._rp_url = rp_url

    def send(self, zipfile_path):
        """Sending zip report to Reporting Portal

        :param string   zipfile_path:     Path to zipfile containing report.

        :return: Response of request to send zip report
        :rtype: Response
        """

        self._check_zipfile(zipfile_path)
        with open(zipfile_path, "rb") as zipfile:
            if self._rp_url:
                response = self._send_to_custom_address(zipfile)
                return response

            err = None
            for dest in self.reporting_portal_endpoints:
                try:
                    zipfile.seek(0)
                    response = Response(
                        requests.post(
                            dest.url,
                            files={"file": ("reporting_portal_report.zip", zipfile)},
                            verify=False,
                        )
                    )
                    response.check_http()
                except (ConnectionError, HTTPConnectionException) as e:
                    err = e
                    logger.warning(
                        f"Failed to send data to: {dest.description}. {dest.retry_message}"
                    )
                    logger.warning(f"Retrying request because of: {e}")
                else:
                    return response
            if err is not None:
                raise err

    def _send_to_custom_address(self, zipfile):
        response = Response(
            requests.post(
                self._rp_url,
                files={"file": ("reporting_portal_report.zip", zipfile)},
                verify=False,
            )
        )
        response.check_http()
        return response

    def _check_zipfile(self, zipfile_path):
        if not os.path.exists(zipfile_path):
            raise FileDoesNotExist(
                f"Specified ZIP file ({zipfile_path}) for Reporting Portal does not exist"
            )


class ReportingPortalConfigValidation:
    REPORTING_PORTAL_URL = (
        "https://rep-portal.wroclaw.nsn-rdnet.net/ute_apis/qc_matcher/"
    )

    def __init__(self, rp_url=None):
        """Class used for managing report sending

        :param string   rp_url: Link used for communication with RP
        """
        self._rp_url = self.REPORTING_PORTAL_URL if rp_url is None else rp_url

    def send(self, configs):
        """Sending zip report to Reporting Portal

        :param ConfigsStore   configs:     List of configs to be checked

        :return: Response of request to validate .qc config
        :rtype: Response
        """
        json_request = json.dumps(configs)
        response = Response(
            requests.post(self._rp_url, data={"data": json_request}, verify=False)
        )
        return response


class ReportingPortalJson:
    JSON_TEMPLATE = {
        "jsonrpc": "2.0",
        "method": None,
        "params": {},
        "id": 0,
    }
    RP_URL = ""

    def __init__(self, rp_url=None):
        """Class used for managing JSON communication with Reporting Portal"""
        self._message_id = generate_md5()
        self._rp_url = self.RP_URL if rp_url is None else rp_url

    @property
    def message_id(self):
        """JSON message ID"""
        return self._message_id

    def send(self, json_cmd):
        """Sending json command to Reporting Portal

        :param dict   json_cmd:     Dictionary containing JSON structure for request

        :return: Response of JSON request
        :rtype: Response
        """
        rpc_to_send = json.dumps(json_cmd)
        response = requests.post(self._rp_url, json=rpc_to_send)
        return Response(response)


class ReportingPortalCrt(ReportingPortalJson):
    RP_URL = "http://rep-portal.wroclaw.nsn-rdnet.net/ute_api/"

    def __init__(self, rp_url=None):
        """Class used for getting CRT status from Reporting Portal

        :param string   json_url:   Link used for getting CRT status from RP
        """
        super().__init__(rp_url)

    def build(
        self,
        test_lab_path=None,
        test_set_name=None,
        test_instance_name=None,
        test_instance_id=None,
    ):
        """Method used for building JSON structure dictionary

        :param string   test_lab_path:      Test lab path in QC
        :param string   test_set_name:      Test set name in QC
        :param string   test_instance_name: Test instance name in QC
        :param string   test_instance_id:   Test instance ID in QC
        """
        json_cmd = copy.deepcopy(self.JSON_TEMPLATE)
        if test_instance_id:
            params = {
                "qc_testlab_path": None,
                "qc_test_set_name": None,
                "qc_test_instance_name": None,
                "qc_id": test_instance_id,
            }
        elif test_lab_path and test_set_name and test_instance_name:
            params = {
                "qc_testlab_path": test_lab_path,
                "qc_test_set_name": test_set_name,
                "qc_test_instance_name": test_instance_name,
                "qc_id": None,
            }
        else:
            raise IncompleteData("Insufficient data")
        json_cmd["params"] = params
        json_cmd["method"] = "get_crt_status"
        json_cmd["id"] = self._message_id
        return json_cmd


class ReportingPortalEvent(ReportingPortalJson):
    RP_URL = "http://rep-portal.wroclaw.nsn-rdnet.net/cloud_manager/events/api"
    alternative_url = "http://10.154.10.233/ute_testline_utilization/api"

    def __init__(self, rp_url=None):
        """Class used for getting CRT status from Reporting Portal

        :param string   events_url: Link used for reporting events to RP
        """
        super().__init__(rp_url)

    def build(self, method, date_time, **kwargs):
        """Method used for building JSON structure dictionary

        :param string               method:     Name of method to be executed. Possible: user_new, user_login,
                                                reservation_new, test_execution_new, test_execution_status
        """
        json_cmd = copy.deepcopy(self.JSON_TEMPLATE)
        params = {"datetime": date_time.isoformat()}
        if kwargs:
            params.update(kwargs)
        else:
            raise IncompleteData("Insufficient data")
        json_cmd["params"] = params
        json_cmd["method"] = method
        json_cmd["id"] = self._message_id
        return json_cmd

    def send(self, json_cmd):
        """Sending json command to Reporting Portal

        :param dict   json_cmd:     Dictionary containing JSON structure for request

        :return: Response of JSON request
        :rtype: Response
        """
        rpc_to_send = json.dumps(json_cmd)
        response = requests.post(self._rp_url, json=rpc_to_send)
        try:
            requests.post(self.alternative_url, json=rpc_to_send)
        except:  # noqa: E722
            pass
        return Response(response)


class Response:
    """Class represents response from Reporting Portal."""

    REPORTING_PORTAL_HASH_URL = (
        "https://rep-portal.wroclaw.nsn-rdnet.net/reports/test-runs/?file_hash={}"
    )

    def __init__(self, response):
        """Class used for extending classic requests-response class

        :param response   response:     Response of requests return message
        """
        self.status_code = response.status_code
        self.text = response.text

    @property
    def json(self):
        """Response converted to JSON"""
        return json.loads(self.text)

    def check_http(self):
        """Check if received response contains good status code."""
        logger.debug(f"Received HTTP code: {self.status_code}")
        if not 200 <= self.status_code < 300:
            raise HTTPConnectionException(
                "Received unexpected response from server\n"
                f"+++HTTP CODE+++\n{self.status_code}\n\n"
                f"+++OUTPUT+++\n{self.text}"
            )

    def check_json(self, json_message_id):
        """Check if received json response contains good message ID and no errors."""
        json_msg = self.json
        if not json_msg["id"] == json_message_id:
            raise WrongMessageId(f'Wrong json message ID: {json_msg["id"]}')
        if "error" in json_msg:
            raise TestInstanceNotExistent(
                f'JSON Error: {json_msg["error"]["data"]["message"]}'
            )

    # TODO: should only have link and saving should be callers responsibility...
    def save_link(self, link_file_path):
        """Save reporting portal link to specified file."""
        rp_link = Response.REPORTING_PORTAL_HASH_URL.format(self.text)
        logger.info(f"Link to reporting portal: {rp_link}")
        with open(link_file_path, "w") as rp_link_file:
            rp_link_file.write(rp_link)
        return rp_link

    # TODO: should only have hash and saving should be callers responsibility...
    def save_hash(self, hash_file_path):
        """Save reporting portal hash to specified file."""
        with open(hash_file_path, "w") as rp_link_file:
            rp_link_file.write(self.text)
